// Datos enviados por el formulario.
const entrada = $input.first().json;
const errores = [];

// Aceptamos texto y eliminamos espacios al principio y al final.
function texto(valor) {
  return typeof valor === 'string' ? valor.trim() : '';
}

// Seleccionamos explícitamente los campos permitidos.
const evento = {
  nombre: texto(entrada.nombre),
  categoria: texto(entrada.categoria),
  descripcion: texto(entrada.descripcion),
  fecha: texto(entrada.fecha),
  hora: texto(entrada.hora),
  lugar: texto(entrada.lugar),
  capacidad: null,
  imagen_url: texto(entrada.imagen_url),
  organizador: texto(entrada.organizador),
  estado: texto(entrada.estado).toUpperCase(),
};

// Límites de texto definidos para EventPass.
const limites = {
  nombre: 150,
  descripcion: 3000,
  lugar: 300,
  organizador: 150,
};

for (const [campo, maximo] of Object.entries(limites)) {
  if (!evento[campo]) {
    errores.push(`${campo}: es obligatorio.`);
  } else if (evento[campo].length > maximo) {
    errores.push(`${campo}: admite hasta ${maximo} caracteres.`);
  }
}

// Solo aceptamos las categorías definidas para el proyecto.
const categorias = [
  'Networking tecnológico',
  'Networking emprendedor',
  'Networking profesional',
];

if (!categorias.includes(evento.categoria)) {
  errores.push('categoria: selecciona una categoría válida.');
}

// Este nodo corresponde únicamente a la creación de eventos.
if (!['BORRADOR', 'PUBLICADO'].includes(evento.estado)) {
  errores.push('estado: debe ser BORRADOR o PUBLICADO.');
}

// Aceptamos capacidad numérica o texto compuesto solo por dígitos.
const capacidadOriginal = entrada.capacidad;

const capacidad = typeof capacidadOriginal === 'number'
  ? capacidadOriginal
  : typeof capacidadOriginal === 'string'
    && /^\d+$/.test(capacidadOriginal.trim())
      ? Number(capacidadOriginal.trim())
      : NaN;

if (!Number.isSafeInteger(capacidad) || capacidad <= 0) {
  errores.push('capacidad: debe ser un número entero mayor que cero.');
} else {
  evento.capacidad = capacidad;
}

// Comprobamos el formato y la existencia real de la fecha.
// Esto evita aceptar fechas como el 30 de febrero.
let fechaValida = false;

if (/^\d{4}-\d{2}-\d{2}$/.test(evento.fecha)) {
  const fechaUTC = new Date(`${evento.fecha}T00:00:00.000Z`);

  fechaValida =
    Number.isFinite(fechaUTC.getTime())
    && fechaUTC.toISOString().slice(0, 10) === evento.fecha;
}

if (!fechaValida) {
  errores.push('fecha: debe ser una fecha real con formato AAAA-MM-DD.');
}

// Hora de 24 horas: desde 00:00 hasta 23:59.
const horaValida = /^([01]\d|2[0-3]):[0-5]\d$/.test(evento.hora);

if (!horaValida) {
  errores.push('hora: utiliza el formato HH:mm; por ejemplo, 18:30.');
}

// Interpretamos la fecha y la hora como hora de Colombia (UTC-05:00).
if (fechaValida && horaValida) {
  const inicioEvento = new Date(
    `${evento.fecha}T${evento.hora}:00-05:00`
  );

  if (inicioEvento.getTime() <= Date.now()) {
    errores.push('fecha y hora: el evento debe comenzar en el futuro.');
  }
}

// La imagen es opcional. Si se proporciona, exigimos una URL HTTPS
// básica, sin espacios ni credenciales. No descargamos la imagen aquí.
if (
  evento.imagen_url
  && (
    evento.imagen_url.length > 2048
    || !/^https:\/\/[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?(?::\d{1,5})?(?:[/?#][^\s]*)?$/i
      .test(evento.imagen_url)
  )
) {
  errores.push('imagen_url: utiliza una dirección HTTPS válida.');
}

// Devolvemos un resultado que el siguiente nodo podrá evaluar.
return [{
  json: {
    valido: errores.length === 0,
    errores,
    evento,
  },
}];

const datos = $input.first().json;

// Protección adicional: este nodo solo debe recibir datos válidos.
if (datos.valido !== true || !datos.evento) {
  throw new Error('No se puede preparar un evento con datos inválidos.');
}

const ahora = new Date().toISOString();

// Cada ejecución de esta instancia tiene su propio identificador.
// Este flujo crea un único evento por ejecución.
const eventoId = `EVT-${$execution.id}`;

return [{
  json: {
    evento_id: eventoId,
    ...datos.evento,
    fecha_creacion: ahora,
    fecha_actualizacion: ahora,
  },
}];

const evento = $input.first().json;

// Convertimos los valores en texto seguro para mostrarlos como HTML.
// Así, una descripción con etiquetas no se ejecuta ni altera la página.
function escaparHTML(valor) {
  const caracteres = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  };

  return String(valor ?? '')
    .replace(/[&<>"']/g, caracter => caracteres[caracter]);
}

// Solo mostramos los campos previstos del evento.
const campos = [
  ['Identificador', evento.evento_id],
  ['Nombre', evento.nombre],
  ['Categoría', evento.categoria],
  ['Descripción', evento.descripcion],
  ['Fecha — AAAA-MM-DD', evento.fecha],
  ['Hora de Colombia', evento.hora],
  ['Lugar', evento.lugar],
  ['Capacidad total', evento.capacidad],
  ['URL de imagen', evento.imagen_url || 'Sin imagen'],
  ['Organizador', evento.organizador],
  ['Estado', evento.estado],
  ['Creación — UTC', evento.fecha_creacion],
  ['Última actualización — UTC', evento.fecha_actualizacion],
];

// Generamos un párrafo por campo y conservamos sus saltos de línea.
const detalleHTML = campos
  .map(([etiqueta, valor]) => {
    const contenido = escaparHTML(valor).replace(/\r?\n/g, '<br>');
    return `<p><strong>${escaparHTML(etiqueta)}:</strong><br>${contenido}</p>`;
  })
  .join('\n');

return [{
  json: {
    evento_id: evento.evento_id,
    detalle_html: detalleHTML,
  },
}];

const propuesta = $('Validar actualización del evento').first().json;

// El elemento vacío producido por Always Output Data no es un evento.
const filas = $input.all()
  .map(item => item.json)
  .filter(fila => fila.evento_id);

const errores = [];

if (filas.length === 0) {
  errores.push('El evento ya no está disponible. Inicia otra consulta.');
} else if (filas.length > 1) {
  errores.push(
    'Hay varias filas con el mismo evento_id. Revisa la integridad de los datos.'
  );
} else {
  const actual = filas[0];
  const original = propuesta.original;

  // Comparamos todos los campos del registro, no solo su fecha.
  const campos = [
    'evento_id', 'nombre', 'categoria', 'descripcion',
    'fecha', 'hora', 'lugar', 'capacidad', 'imagen_url',
    'organizador', 'estado', 'fecha_creacion', 'fecha_actualizacion',
  ];

  const cambio = campos.some(campo =>
    String(actual[campo] ?? '') !== String(original[campo] ?? '')
  );

  if (cambio) {
    errores.push(
      'El evento cambió mientras lo editabas. Abre nuevamente el formulario para cargar la versión actual.'
    );
  }
}

return [{
  json: {
    valido: errores.length === 0,
    errores,
    evento: propuesta.evento,
    original: propuesta.original,
  },
}];

const propuesta = $('Comprobar cambios del evento').first().json;
const eventoId = String(propuesta.evento.evento_id);

// Ignoramos únicamente el objeto vacío de una consulta sin resultados.
const filas = $input.all()
  .map(item => item.json)
  .filter(fila => Object.keys(fila).length > 0);

// Si la consulta devuelve datos inesperados, detenemos la ejecución.
// No continuamos con un conteo posiblemente incorrecto.
for (const fila of filas) {
  if (
    !fila.inscripcion_id ||
    String(fila.evento_id) !== eventoId ||
    fila.estado !== 'CONFIRMADA'
  ) {
    throw new Error(
      'La consulta de confirmadas devolvió datos inesperados. Revisa los filtros y los registros.'
    );
  }
}

const confirmadas = filas.length;
const capacidad = propuesta.evento.capacidad;
const errores = [];

if (!Number.isSafeInteger(capacidad) || capacidad <= 0) {
  errores.push('La capacidad debe ser un número entero mayor que cero.');
} else if (capacidad < confirmadas) {
  errores.push(
    `Hay ${confirmadas} inscripciones confirmadas. La capacidad no puede ser menor que ${confirmadas}.`
  );
}

return [{
  json: {
    valido: errores.length === 0,
    errores,
    confirmadas,
    evento: propuesta.evento,
    original: propuesta.original,
  },
}];

// Datos enviados por el formulario.
// Datos editados por el administrador.
const formulario = $input.first().json;

// Registro original leído antes de abrir la página de edición.
// Esta rama debe trabajar con un único evento.
const original = $('Buscar evento para actualizar').first().json;

if (!original.evento_id || !original.fecha_actualizacion) {
  throw new Error(
    'El registro original no tiene identificador o fecha de actualización.'
  );
}

// El estado se recupera del registro original.
// No permitimos cambiarlo enviando un campo adicional en el formulario.
const entrada = {
  ...formulario,
  estado: original.estado,
};

const errores = [];

// Aceptamos texto y eliminamos espacios al principio y al final.
function texto(valor) {
  return typeof valor === 'string' ? valor.trim() : '';
}

// Seleccionamos explícitamente los campos permitidos.
const evento = {
  nombre: texto(entrada.nombre),
  categoria: texto(entrada.categoria),
  descripcion: texto(entrada.descripcion),
  fecha: texto(entrada.fecha),
  hora: texto(entrada.hora),
  lugar: texto(entrada.lugar),
  capacidad: null,
  imagen_url: texto(entrada.imagen_url),
  organizador: texto(entrada.organizador),
  estado: texto(entrada.estado).toUpperCase(),
};

// Límites de texto definidos para EventPass.
const limites = {
  nombre: 150,
  descripcion: 3000,
  lugar: 300,
  organizador: 150,
};

for (const [campo, maximo] of Object.entries(limites)) {
  if (!evento[campo]) {
    errores.push(`${campo}: es obligatorio.`);
  } else if (evento[campo].length > maximo) {
    errores.push(`${campo}: admite hasta ${maximo} caracteres.`);
  }
}

// Solo aceptamos las categorías definidas para el proyecto.
const categorias = [
  'Networking tecnológico',
  'Networking emprendedor',
  'Networking profesional',
];

if (!categorias.includes(evento.categoria)) {
  errores.push('categoria: selecciona una categoría válida.');
}

// Este nodo corresponde únicamente a la creación de eventos.
// Regla de edición: solo permitimos modificar eventos en estos estados.
// Los eventos cerrados o cancelados conservarán su información histórica.
if (!['BORRADOR', 'PUBLICADO'].includes(evento.estado)) {
  errores.push(
    'Solo se pueden editar eventos en estado BORRADOR o PUBLICADO.'
  );
}

// Aceptamos capacidad numérica o texto compuesto solo por dígitos.
const capacidadOriginal = entrada.capacidad;

const capacidad = typeof capacidadOriginal === 'number'
  ? capacidadOriginal
  : typeof capacidadOriginal === 'string'
    && /^\d+$/.test(capacidadOriginal.trim())
      ? Number(capacidadOriginal.trim())
      : NaN;

if (!Number.isSafeInteger(capacidad) || capacidad <= 0) {
  errores.push('capacidad: debe ser un número entero mayor que cero.');
} else {
  evento.capacidad = capacidad;
}

// Comprobamos el formato y la existencia real de la fecha.
// Esto evita aceptar fechas como el 30 de febrero.
let fechaValida = false;

if (/^\d{4}-\d{2}-\d{2}$/.test(evento.fecha)) {
  const fechaUTC = new Date(`${evento.fecha}T00:00:00.000Z`);

  fechaValida =
    Number.isFinite(fechaUTC.getTime())
    && fechaUTC.toISOString().slice(0, 10) === evento.fecha;
}

if (!fechaValida) {
  errores.push('fecha: debe ser una fecha real con formato AAAA-MM-DD.');
}

// Hora de 24 horas: desde 00:00 hasta 23:59.
const horaValida = /^([01]\d|2[0-3]):[0-5]\d$/.test(evento.hora);

if (!horaValida) {
  errores.push('hora: utiliza el formato HH:mm; por ejemplo, 18:30.');
}

// Interpretamos la fecha y la hora como hora de Colombia (UTC-05:00).
if (fechaValida && horaValida) {
  const inicioEvento = new Date(
    `${evento.fecha}T${evento.hora}:00-05:00`
  );

  if (inicioEvento.getTime() <= Date.now()) {
    errores.push('fecha y hora: el evento debe comenzar en el futuro.');
  }
}

// La imagen es opcional. Si se proporciona, exigimos una URL HTTPS
// básica, sin espacios ni credenciales. No descargamos la imagen aquí.
if (
  evento.imagen_url
  && (
    evento.imagen_url.length > 2048
    || !/^https:\/\/[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?(?::\d{1,5})?(?:[/?#][^\s]*)?$/i
      .test(evento.imagen_url)
  )
) {
  errores.push('imagen_url: utiliza una dirección HTTPS válida.');
}

// Devolvemos un resultado que el siguiente nodo podrá evaluar.
return [{
  json: {
    valido: errores.length === 0,
    errores,

    // Datos propuestos, todavía sin guardar.
    evento: {
      ...evento,
      evento_id: original.evento_id,
      fecha_creacion: original.fecha_creacion,
    },

    // Conservamos el registro leído al abrir el formulario.
    // Después lo compararemos con una nueva lectura de Sheets.
    original: {
      ...original,
    },
  },
}];

const datos = $input.first().json;

if (datos.valido !== true || !datos.evento || !datos.original) {
  throw new Error('La actualización no superó los controles previos.');
}

const camposEditables = [
  'nombre',
  'categoria',
  'descripcion',
  'fecha',
  'hora',
  'lugar',
  'capacidad',
  'imagen_url',
  'organizador',
];

// Registramos qué campos cambiaron y sus valores anteriores y nuevos.
const cambios = {};

for (const campo of camposEditables) {
  const anterior = datos.original[campo] ?? '';
  const nuevo = datos.evento[campo] ?? '';

  if (String(anterior) !== String(nuevo)) {
    cambios[campo] = { anterior, nuevo };
  }
}

const ahora = new Date().toISOString();

// Construimos explícitamente los campos que podrán escribirse.
const evento = {
  evento_id: datos.original.evento_id,
};

for (const campo of camposEditables) {
  evento[campo] = datos.evento[campo];
}

evento.fecha_actualizacion = ahora;

return [{
  json: {
    evento,
    auditoria: {
      auditoria_id: `AUD-UPDATE-${$execution.id}`,
      evento_id: evento.evento_id,
      accion: 'UPDATE',
      fecha: ahora,
      resultado: 'EXITO',
      detalle: JSON.stringify({
        origen: 'FORMULARIO_ADMINISTRATIVO',
        cambios,
      }),
    },
  },
}];
